// Brief: 章节信息，表示视频中的一个章节，包含时间范围和标题。

/// 章节信息
///
/// 表示视频中的一个章节，包含时间范围和标题。
/// 通常由视频拆条（将长视频按内容/语义拆分为多个片段）后生成，
/// BottomBarSlot 在进度条上绘制章节标记点，
/// 以及用户 Seek 时显示当前章节信息。
///
/// Chapter Info
///
/// Represents a chapter in the video with time range and title.
/// Typically generated by video segmentation (splitting a long video
/// into multiple segments based on content/semantics).
/// Used for drawing chapter markers on the progress bar and displaying
/// chapter info during seek when chapter data is provided.
class ChapterInfo {
  /// 章节唯一标识（可选）
  ///
  /// 用于 AI 场景下后端数据关联，非 AI 场景可为 null。
  ///
  /// Optional chapter ID for backend data association in AI scenarios.
  final String? id;

  /// 章节开始时间，单位毫秒
  ///
  /// Chapter start time in milliseconds
  final int startMs;

  /// 章节结束时间，单位毫秒
  ///
  /// Chapter end time in milliseconds
  final int endMs;

  /// 章节标题
  ///
  /// Chapter title
  final String title;

  /// 章节缩略图 URL
  ///
  /// Chapter thumbnail URL
  final String? thumbnailUrl;

  /// 构造函数
  ///
  /// Constructor
  ChapterInfo({
    this.id,
    required this.startMs,
    required this.endMs,
    required this.title,
    this.thumbnailUrl,
  })  : assert(
          startMs >= 0,
          'startMs must be non-negative, got: $startMs',
        ),
        assert(
          endMs >= startMs,
          'endMs must be >= startMs, got startMs=$startMs, endMs=$endMs',
        );

  /// 从 JSON 映射创建 [ChapterInfo] 实例
  ///
  /// Create a [ChapterInfo] instance from a JSON map
  factory ChapterInfo.fromJson(Map<String, dynamic> json) {
    final startMs = (json['startMs'] as num?)?.toInt() ?? 0;
    final endMs = (json['endMs'] as num?)?.toInt() ?? startMs;

    return ChapterInfo(
      id: json['id'] as String?,
      startMs: startMs,
      endMs: endMs,
      title: json['title'] as String? ?? '',
      thumbnailUrl: json['thumbnailUrl'] as String?,
    );
  }

  /// 转换为 JSON 映射
  ///
  /// Convert to a JSON map
  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'startMs': startMs,
      'endMs': endMs,
      'title': title,
      'thumbnailUrl': thumbnailUrl,
    };
  }

  /// 根据播放位置查找当前章节索引（二分查找，O(log n)）
  ///
  /// 前提条件：[chapters] 必须按 [startMs] 升序排列，且章节区间连续不重叠。
  /// 如果传入未排序的列表，二分查找将返回错误结果。
  ///
  /// Find chapter index by playback position using binary search (O(log n)).
  /// Prerequisite: [chapters] must be sorted by [startMs] in ascending order,
  /// and chapter intervals must be continuous and non-overlapping.
  /// Passing an unsorted list will produce incorrect results.
  ///
  /// [chapters] 章节列表
  /// [positionMs] 当前播放位置（毫秒）
  /// 返回当前章节索引，未找到返回 -1
  static int findIndexByPosition(List<ChapterInfo>? chapters, int positionMs) {
    if (chapters == null || chapters.isEmpty) return -1;

    int low = 0;
    int high = chapters.length - 1;

    while (low <= high) {
      final int mid = (low + high) >>> 1;
      final ChapterInfo chapter = chapters[mid];
      if (positionMs < chapter.startMs) {
        high = mid - 1;
      } else if (positionMs >= chapter.endMs) {
        low = mid + 1;
      } else {
        return mid;
      }
    }
    return -1;
  }

  @override
  String toString() {
    return 'ChapterInfo{id: $id, startMs: $startMs, endMs: $endMs, '
        'title: $title, thumbnailUrl: $thumbnailUrl}';
  }
}
